INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(3523000, 3523, 0, 1, 0, 0, 0, 0, 'Netherstorm', 'Once Farahlon, a lush land of forests and open range on the Devouring Sea. When Ner''zhul''s portals tore Draenor apart, it broke into seven great floating islands and thousands of lesser shards drifting in the Twisting Nether. Here the Nether and the physical world bleed into each other. Lightning arcs through violet haze, bands of raw magic wrap the sky, and the Nether eats away at the edges of the land.\n\nThe bedrock and soil have turned a sickly purple that supports no plant life. All that is left of Farahlon''s forests survives under the ethereals'' great domes.', 'warcraft.wiki.gg: Netherstorm (introduction, Recent history, Geography)'),
(3523001, 3523, 1, 1, 0, 0, 0, 0, 'The Manaforges', 'When Kael''thas'' blood elves reached the Netherstorm, they seized Tempest Keep, dismantled parts of it, and built five tremendous manaforges across the islands. The forges draw mana out of the Twisting Nether itself and store it in cells for the elves to feed on. They were never meant to be used so close to land, and they are tearing the Netherstorm apart. Demons of the Legion have been seen among the elves at Manaforge Ara, which may say something about where Kael''thas'' loyalties now lie.', 'warcraft.wiki.gg: Netherstorm (The Burning Crusade); warcraft.wiki.gg: Manaforge Ara'),
(3523002, 3523, 1, 2, 0, 0, 0, 0, 'Manaforge Ultris', 'The fifth manaforge, run beyond its capacity until it exploded and tore a hole in reality. Creatures of the Void came through and took it. In the mine beneath it, the corpses of slain blood elves carry parasitic fleshbeasts that burst out of their hosts at anyone who comes near.', 'warcraft.wiki.gg: Manaforge Ultris; warcraft.wiki.gg: Access Shaft Zeon'),
(3523003, 3523, 1, 3, 0, 0, 0, 0, 'Area 52', 'A goblin town built like Gadgetzan or Everlook, behind a short wall on the south-western island. The goblins came to study and experiment in this unique place. They are building the X-52 Nether-Rocket to fly into the Twisting Nether in search of new technology and business, and they send bombs to the troops fighting the Legion in Hellfire.', 'warcraft.wiki.gg: Area 52; warcraft.wiki.gg: Netherstorm (The Burning Crusade)'),
(3523004, 3523, 1, 4, 0, 0, 0, 0, 'The Stormspire', 'A draenei-built town under the twin eco-domes, with no draenei left in it. The ethereal Consortium runs it now. Its leader, Nexus-Prince Haramad, oversees it from the top of the spire as a hologram and does business with Prince Kael''thas and the forces of Azeroth alike. Many of the goods sold here are smuggled past the naaru''s prohibitions and the goblins'' taxes. The Legion''s forge bases next door attack it constantly.', 'warcraft.wiki.gg: Stormspire'),
(3523005, 3523, 1, 5, 0, 0, 0, 0, 'The Eco-Domes', 'Great magical domes raised by the ethereals and visible from nearly anywhere in the Netherstorm. Inside them, the ethereals preserve the last of the region''s greenery, though not every creature in them is native to Farahlon.', 'warcraft.wiki.gg: Netherstorm (introduction, The Burning Crusade); warcraft.wiki.gg: Eco-Dome Farfield'),
(3523006, 3523, 1, 6, 0, 0, 0, 0, 'Kirin''Var Village', 'When the Alliance expedition came to Draenor, a group of Kirin Tor wizards under Archmage Vargoth built a village in the heart of Laughing Skull territory and survived the orcs'' assaults. Then Draenor tore apart, and they held on for seventeen years among the wreckage.\n\nKael''thas'' forces came with more power than they could imagine and destroyed the village with a mana bomb. Vargoth''s wizards retreated into their tower, and Kael''thas sealed it with a curse so that none could leave. Now the dead of Kirin''Var haunt the streets, most of them living on as if they had never died.', 'warcraft.wiki.gg: Kirin''Var Village (History, Current state)'),
(3523007, 3523, 1, 7, 0, 0, 0, 0, 'The Legion''s Bases', 'The Burning Legion has staked its own claim here: two forge bases, one that sends wrathguards and shivarra through its teleporters against the Stormspire and one that assembles fel reavers, and demons digging through the Arklon ruins.', 'warcraft.wiki.gg: Forge Base: Gehenna; warcraft.wiki.gg: Forge Base: Oblivion; warcraft.wiki.gg: Netherstorm (The Burning Crusade)'),
(3523008, 3523, 1, 8, 0, 0, 0, 0, 'Socrethar''s Seat', 'A whole floating island in the far north-west, the throne of Socrethar, an eredar who leads the Legion in the Netherstorm. Below it lie the ruins of Farahlon, once a great draenei city, where a dreadlord named Culuthas slew Socrethar''s own demons and summoned void terrors of his own.', 'warcraft.wiki.gg: Socrethar''s Seat; warcraft.wiki.gg: Ruins of Farahlon; warcraft.wiki.gg: Socrethar'),
(3523009, 3523, 1, 9, 0, 0, 0, 0, 'The Ruins of Enkaat', 'All that is left of a draenei town. From the skeletons and the crates of belongings scattered through it, its people were being evacuated when it was destroyed. Spectral vindicators still wander among the ruins.', 'warcraft.wiki.gg: Ruins of Enkaat'),
(3523010, 3523, 1, 10, 0, 0, 0, 0, 'The Protectorate', 'The Protectorate, a faction of ethereals, keeps a watch post on the doorstep of the rival Ethereum and of the Void at Manaforge Ultris. It is understaffed and cannot strike at either alone.', 'warcraft.wiki.gg: Protectorate Watch Post; warcraft.wiki.gg: Ethereum Staging Grounds'),
(3523011, 3523, 1, 11, 0, 0, 0, 0, 'Netherstone', 'Crystal spires in the north, thick with well-hidden Farahlon colossi, a source of the rare crystal farahlite.', 'warcraft.wiki.gg: Netherstone'),
(3523012, 3523, 1, 12, 0, 0, 0, 0, 'Tempest Keep', 'A dimensional fortress of the naaru, able to travel through the Twisting Nether from place to place in the blink of an eye, a self-contained Dark Portal. A''dal, M''uru and O''ros brought it to Outland to help its people. Kael''thas raided it and took its satellite wings for himself. One wing escaped: Velen''s draenei stole the Exodar and fled in it to Azeroth.', 'warcraft.wiki.gg: Tempest Keep (History, Functioning)'),
(3523013, 3523, 1, 13, 0, 0, 0, 0, 'The Crumbling Waste', 'The broken edges of the Netherstorm, where the land crumbles away into the Nether.', 'warcraft.wiki.gg: Crumbling Waste');
